function normUrl(u){u=str(u);if(!u)return '';u=u.split('#')[0];var m=u.match(/^(https?):\/\/([^\/?]+)([^?]*)(\?.*)?$/i);if(!m)return u.toLowerCase();var path=m[3]||'/';if(path.length>1&&path.slice(-1)==='/')path=path.slice(0,-1);return m[1].toLowerCase()+'://'+m[2].toLowerCase()+(path||'/')+(m[4]||'');}
// Canonical Avito listing URL: strip query/hash ONLY when the path carries a listing id (safe).
function canonUrl(u){u=str(u);if(!u)return '';var base=u.split('#')[0].split('?')[0];if(base.length>1&&base.slice(-1)==='/')base=base.slice(0,-1);var path=base.replace(/^https?:\/\/[^\/]+/i,'');if(/_(\d{6,})$/.test(path)||/\/(\d{7,})$/.test(path)){return base;}return u;}
// Decoded URL slug ("yuridicheskiy_adres_dlya_ooo_…" -> "yuridicheskiy adres dlya ooo …") as relevance evidence.
function slugText(u){u=str(u);if(!u)return '';var path=u.split('#')[0].split('?')[0].replace(/^https?:\/\/[^\/]+/i,'');var segs=path.split('/').filter(Boolean);var s=segs.length?segs[segs.length-1]:'';s=s.replace(/_\d{6,}$/,'');return s.replace(/[_-]+/g,' ').toLowerCase();}
function hashText(s){s=str(s);let h=5381;for(let i=0;i<s.length;i++){h=((h<<5)+h+s.charCodeAt(i))>>>0;}return ('00000000'+h.toString(16)).slice(-8);}
function cut(s,n){s=str(s);return s.length>n?s.slice(0,n):s;}
function detectPlaceholderTitle(t){t=str(t);if(!t)return false;if(/ещ[её]\s*\d+\s*фото/i.test(t))return true;if(/^\s*\+?\d+\s*фото\s*$/i.test(t))return true;if(/^\s*\d+\s*(фото|photos?|images?)\s*$/i.test(t))return true;return false;}
function kwHit(blob,tok){ if(tok.length<=3){ return new RegExp('(^|[^а-яёa-z0-9])'+tok+'([^а-яёa-z0-9]|$)','i').test(blob);} return blob.indexOf(tok)>=0; }
