// Dedup normalized listings vs market_record_registry (by dedup_key) + within batch. No external calls.
// DEC-094: drop INVALID live items (empty/search-only) before dedup.
// DEC-095: hard-skip live false positives (hard-negative / query-only) BEFORE pipeline_limit —
// pipeline_limit applies only to accepted business-relevant records; hard negatives never consume the cap.
function str(v){return v==null?'':String(v).trim();}
const cfg=$('Set Avito Connector Config').first().json;
const approvalUnique=str(cfg.approval_status_for_unique)||'new';
const dupNext=str(cfg.duplicate_next_action)||'monitor_duplicate';
const fixtureMode=(cfg.fixture_mode===true||str(cfg.fixture_mode).toLowerCase()==='true');
const pipelineLimit=Number(cfg.pipeline_limit)||Number(cfg.live_max_items)||10;
const recs=$('Normalize Avito Listings').all().map(i=>i.json);
let reg=[];
try{reg=$('Read market_record_registry').all().map(i=>i.json).filter(Boolean);}catch(e){reg=[];}
const regSet=new Set(reg.map(r=>str(r&&r.dedup_key)).filter(Boolean));
const seen=new Set();
const out=[];
let acceptedCount=0;
for(const r of recs){
  // Invalid live items: never registered, never counted unique, never written as competitor.
  if(r.is_valid_listing===false){
    out.push({ json: Object.assign({}, r, { dedup_status:'invalid', approval_status:'invalid', next_action:'ignore' }) });
    continue;
  }
  // DEC-095: live hard-negative / query-only false positives are filtered BEFORE the pipeline cap
  // and are NOT written to raw_market_records (by default) or market_record_registry.
  if(!fixtureMode && r.hard_skip===true){
    out.push({ json: Object.assign({}, r, { dedup_status:'hard_skipped', approval_status:'skipped_irrelevant', next_action:'ignore' }) });
    continue;
  }
  // Live pipeline cap: write at most pipeline_limit accepted business-relevant listings.
  if(!fixtureMode && acceptedCount>=pipelineLimit){
    out.push({ json: Object.assign({}, r, { dedup_status:'over_pipeline_limit', approval_status:'skipped', next_action:'ignore' }) });
    continue;
  }
  acceptedCount++;
  const key=str(r.dedup_key);
  let dedup_status='unique';
  let approval_status=approvalUnique;
  let next_action=str(r.next_action);
  if(key&&regSet.has(key)){
    dedup_status='duplicate_in_registry';approval_status='duplicate';
    next_action=(str(r.record_type_hint)==='irrelevant')?'ignore':dupNext;
  } else if(key&&seen.has(key)){
    dedup_status='duplicate_in_batch';approval_status='duplicate';
    next_action=(str(r.record_type_hint)==='irrelevant')?'ignore':dupNext;
  } else {
    dedup_status='unique';if(key)seen.add(key);
  }
  out.push({ json: Object.assign({}, r, { dedup_status:dedup_status, approval_status:approval_status, next_action:next_action }) });
}
return out;

